import { Component, Input } from '@angular/core';
import { StringUtil } from '../../../../utils/string/string.utils';
import { FlexTableColumn } from '../../interfaces/flex-table.interface';
interface BgClass {
  color: string;
  opacity: string;
  fontWeight: string;
  ['background-color']: string;
}
@Component({
  selector: 'dx-flex-table-text-cell',
  templateUrl: './flex-table-text-cell.component.html',
  styleUrls: ['./flex-table-text-cell.component.scss'],
})
export class FlexTableTextCellComponent<T> {
  @Input() color!: string;
  @Input() column!: FlexTableColumn<T>;
  copyText: string = 'Click to copy';
  static readonly DEFAULT_TEXT: string = '-';

  text: string = FlexTableTextCellComponent.DEFAULT_TEXT;

  private _data!: string | number;
  private _defaultText: string = FlexTableTextCellComponent.DEFAULT_TEXT;

  @Input()
  set data(val: string | number) {
    if (this._data !== val) {
      this._data = val;
      this.updateText();
    }
  }

  get data(): string | number {
    return this._data;
  }

  @Input()
  set defaultText(val: string) {
    if (this._defaultText !== val) {
      this._defaultText = val;
      this.updateText();
    }
  }

  get defaultText(): string {
    return this._defaultText;
  }

  private updateText(): void {
    const tmp: string =
      !this.data
        ? this.defaultText
        : String(this.data);

    this.text = StringUtil.isBlank(tmp) ? this.defaultText : tmp;
  }

  showBackgroundColor(column: boolean, color: string): BgClass | undefined {
    if (column == true && color) {
      let ngclass: BgClass = {
        color: color,
        opacity: '0.9',
        'background-color': `${color + '38'}`,
        fontWeight: 'bold',
      };
      return ngclass;
    } else {
      return undefined;
    }
  }
  onClickCopy(): void {
    this.copyText = 'Copied';
  }
  changeText(): void {
    this.copyText = 'Click to copy';
  }
}

