import { Injectable, Inject, Optional } from '@angular/core';
import { AvatarConfig } from '../model/avatar-config';
import { AVATAR_CONFIG } from '../model/avatar-config.token';
import { AvatarSource } from '../model/avatar-source.enum';

@Injectable()
export class AvatarConfigService {
  constructor(
    @Optional()
    @Inject(AVATAR_CONFIG)
    public userConfig: AvatarConfig
  ) {}

  public getAvatarSources(defaultSources: AvatarSource[]): AvatarSource[] {
    if (
      this.userConfig &&
      this.userConfig.sourcePriorityOrder &&
      this.userConfig.sourcePriorityOrder.length
    ) {
      const uniqueSources = [...new Set(this.userConfig.sourcePriorityOrder)];
      const validSources = uniqueSources.filter(source =>
        defaultSources.includes(source)
      );
      return [
        ...validSources,
        ...defaultSources.filter(source => !validSources.includes(source))
      ];
    }
    return defaultSources;
  }

  public getAvatarColors(defaultColors: string[]): string[] {
    return (
      (this.userConfig &&
        this.userConfig.colors &&
        this.userConfig.colors.length &&
        this.userConfig.colors) ||
      defaultColors
    );
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

import { Observable } from 'rxjs';

import { AvatarConfigService } from './avatar-config.service';
import { AvatarSource } from '../model/avatar-source.enum';
import { Source } from '../model/source';

/**
 * list of Supported avatar sources
 */
export const defaultSources = [
  AvatarSource.FACEBOOK,
  AvatarSource.GOOGLE,
  AvatarSource.TWITTER,
  AvatarSource.INSTAGRAM,
  AvatarSource.VKONTAKTE,
  AvatarSource.SKYPE,
  AvatarSource.GRAVATAR,
  AvatarSource.GITHUB,
  AvatarSource.CUSTOM,
  AvatarSource.INITIALS,
  AvatarSource.VALUE
];

/**
 * list of default colors
 */
export const defaultColors = [
  '#1abc9c',
  '#3498db',
  '#f1c40f',
  '#8e44ad',
  '#e74c3c',
  '#d35400',
  '#2c3e50',
  '#7f8c8d'
];

/**
 * Provides utilities methods related to Avatar component
 */
@Injectable()
export class AvatarService {
  public avatarSources: AvatarSource[] = defaultSources;
  public avatarColors: string[] = defaultColors;

  private readonly failedSources = new Map<string, Source>();

  constructor(
    private http: HttpClient,
    private avatarConfigService: AvatarConfigService
  ) {
    this.overrideAvatarSources();
    this.overrideAvatarColors();
  }

  public fetchAvatar(avatarUrl: string): Observable<unknown> {
    return this.http.get(avatarUrl);
  }

  public getRandomColor(avatarText: string): string {
    if (!avatarText) {
      return 'transparent';
    }
    const asciiCodeSum = this.calculateAsciiCode(avatarText);
    return this.avatarColors[asciiCodeSum % this.avatarColors.length];
  }

  public compareSources(
    sourceType1: AvatarSource,
    sourceType2: AvatarSource
  ): number {
    return (
      this.getSourcePriority(sourceType1) - this.getSourcePriority(sourceType2)
    );
  }

  public isSource(source: string): boolean {
    return this.avatarSources.includes(source as AvatarSource);
  }

  public isTextAvatar(sourceType: AvatarSource): boolean {
    return [AvatarSource.INITIALS, AvatarSource.VALUE].includes(sourceType);
  }

  private buildSourceKey(source: Source): string {
    return source.sourceType + '-' + source.sourceId;
  }

  public sourceHasFailedBefore(source: Source): boolean {
    return this.failedSources.has(this.buildSourceKey(source));
  }

  public markSourceAsFailed(source: Source): void {
    this.failedSources.set(this.buildSourceKey(source), source);
  }

  private overrideAvatarSources(): void {
    this.avatarSources = this.avatarConfigService.getAvatarSources(
      defaultSources
    );
  }

  private overrideAvatarColors(): void {
    this.avatarColors = this.avatarConfigService.getAvatarColors(defaultColors);
  }

  private calculateAsciiCode(value: string): number {
    return value
      .split('')
      .map(letter => letter.charCodeAt(0))
      .reduce((previous, current) => previous + current);
  }

  private getSourcePriority(sourceType: AvatarSource) {
    return this.avatarSources.indexOf(sourceType);
  }
}

import { Injectable } from '@angular/core';

export interface ColumnInfo {
  id: string;
  name: string;
  hidden: boolean;
}

@Injectable()
export class ColumnSorterService {
  loadSavedColumnInfo(columnInfo: ColumnInfo[], saveName?: string): ColumnInfo[]{
    // Only load if a save name is passed in
    if (saveName) {
      if (!localStorage) {
        return [];
      }

      const loadedInfo = localStorage.getItem(`${saveName}-columns`);

      if (loadedInfo) {
        return JSON.parse(loadedInfo) ?? [];
      }
      this.saveColumnInfo(columnInfo);
      return columnInfo ?? [];
    }
    return []
  }

  saveColumnInfo(columnInfo: ColumnInfo[], saveName?: string): void {
    // Only save if a save name is passed in
    if (saveName) {
      if (!localStorage) {
        return ;
      }

      localStorage.setItem(`${saveName}-columns`, JSON.stringify(columnInfo));
    }
  }
}

import { Injectable } from "@angular/core";
import { Action, Selector, State, StateContext } from "@ngxs/store";
import { ActiveMenu, MENU, Menu, SubMenu } from "../../model/menu";
import { SetActiveMenu, SetActivePage, SetCurrentRouting, SetLayoutType, SetMenu, SetSubMenuStatus } from "./layout.action";
import { LAYOUT, LayoutModel, SUB_MENU_TYPE } from "./layout.model";

@State<LayoutModel>({
    name: LayoutState.STORE,
    defaults: {
        layout: 'layout-1',
        subOpen: 'in',
        menu: [],
        activeMenu: undefined,
        subMenu: [],
        active: {
            menu: 'HOME',
            subMenu: undefined,
        },
        currentPage: {
            parentCode: 'HOME',
            childCode: undefined
        }
    },
})
@Injectable()
export class LayoutState {
    static STORE: string = 'NgDxLayout';

    @Selector()
    static getLayout(state: LayoutModel): LAYOUT {
        return state?.layout;
    }

    @Selector()
    static isDashboard(state: LayoutModel): boolean {
        return state?.active?.menu === 'HOME';
    }

    @Selector()
    static getSubOpen(state: LayoutModel): SUB_MENU_TYPE {
        return state?.subOpen;
    }

    @Selector()
    static getSubMenu(
        state: LayoutModel
    ): SubMenu[] {
        return state.subMenu
    }

    @Selector()
    static getMenu(state: LayoutModel): Menu[] {
        return state?.menu;
    }

    @Selector()
    static getActiveMenu(state: LayoutModel): ActiveMenu {
        return state?.active;
    }

    @Action(SetLayoutType)
    setLayoutType(
        ctx: StateContext<LayoutModel>,
        action: SetLayoutType
    ): void {
        ctx.patchState({
            layout: action.layout
        });
    }

    @Action(SetSubMenuStatus)
    setSubMenuStatus(
        ctx: StateContext<LayoutModel>,
        action: SetSubMenuStatus
    ): void {
        console.log(action)
        ctx.patchState({
            subOpen: action.layoutStatus
        });
    }

    @Action(SetActivePage)
    setActivePage(
        ctx: StateContext<LayoutModel>,
        action: SetActivePage
    ): void {
        console.log(action)
        ctx.patchState({
            currentPage: {
                parentCode: action.parentId
            }
        });
    }

    @Action(SetMenu)
    setMenu(
        ctx: StateContext<LayoutModel>,
        action: SetMenu
    ): void {
        const activeMenu: Menu | undefined = action.menu.find((item: Menu) => item.active);
        ctx.patchState({
            menu: action.menu,
            activeMenu: activeMenu,
        });
    }

    @Action(SetActiveMenu)
    setActiveMenu(
        ctx: StateContext<LayoutModel>,
        action: SetActiveMenu
    ): void {
        const menu: Menu[] = ctx.getState().menu;
        ctx.patchState({
            // subOpen: ctx.getState().active.menu !== action.menu.code ? 'out' : ctx.getState().subOpen,
            subOpen: 'in',
            activeMenu: action.menu,
            active: {
                menu: action.menu.code as MENU,
                subMenu: ctx.getState()?.active?.subMenu
            },
            subMenu: menu.find((item: Menu) => item.code === action.menu.code)?.children ?? [],
            menu: menu.map((item: Menu) => {
                return {
                    ...item,
                    active: action.menu.code === item.code
                };
            }),
        });
    }



    @Action(SetCurrentRouting)
    setCurrentRouting(
        ctx: StateContext<LayoutModel>,
        action: SetCurrentRouting
    ): void {
        const menu: Menu[] = ctx.getState().menu;
        const isChild: Menu | undefined = menu.find((menu: Menu) => menu.code === action.menu.menu);
        ctx.patchState({
            activeMenu: isChild,
            active: {
                menu: action.menu.menu ?? undefined,
                subMenu: action.menu.subMenu,
            },
            subMenu: isChild?.children ?? [],
            menu: menu.map((item: Menu) => {
                return {
                    ...item,
                    active: action.menu.menu === item.code
                };
            }),
        });
    }
}

import { Injectable } from '@angular/core';
import { Store } from '@ngxs/store';
import { Observable } from 'rxjs';
import { ActiveMenu, Menu, SubMenu } from '../../model/menu';
