import { LAYOUT, SUB_MENU_TYPE } from '../state/layout.model';
import { LayoutState } from '../state/layout.state';

@Injectable({
  providedIn: 'root'
})
export class NgDxLayoutService {

  constructor(
    private store: Store) { }


  setLayoutType(layout: LAYOUT): void {
    this.store.dispatch(new SetLayoutType(layout));
  }

  setCurrentRouting(menu: ActiveMenu): void {
    this.store.dispatch(new SetCurrentRouting(menu));
  }

  setMenu(menu: Menu[]): void {
    this.store.dispatch(new SetMenu(menu));
  }

  setActivePage(parentCode: string): void {
    this.store.dispatch(new SetActivePage(parentCode));
  }

  setSubMenuStatus(subMenu: SUB_MENU_TYPE): void {
    this.store.dispatch(new SetSubMenuStatus(subMenu));
  }

  setActiveMenu(menu: Menu): void {
    this.store.dispatch(new SetActiveMenu(menu));
  }



  getLayout(): Observable<LAYOUT> {
    return this.store.select(LayoutState.getLayout);
  }

  getSubOpen(): Observable<SUB_MENU_TYPE> {
    return this.store.select(LayoutState.getSubOpen);
  }

  getMenu(): Observable<Menu[]> {
    return this.store.select(LayoutState.getMenu);
  }

  getSubMenu(): Observable<SubMenu[]> {
