  /** a reference to the component see portal.ts */
  portal: ComponentRef<C>;
  /** a reference to your toast */
  toastRef: ToastRef<C>;
  /** triggered when toast is active */
  onShown: Observable<void>;
  /** triggered when toast is destroyed */
  onHidden: Observable<void>;
  /** triggered on toast click */
  onTap: Observable<void>;
  /** available for your use in custom toast */
  onAction: Observable<any>;
}

@Injectable({ providedIn: 'root' })
export class ToastrService {
  toastrConfig: GlobalConfig;
  currentlyActive = 0;
  toasts: ActiveToast<any>[] = [];
  overlayContainer?: ToastContainerDirective;
  previousToastMessage: string | undefined;
  private index = 0;

  constructor(
    @Inject(TOAST_CONFIG) token: ToastToken,
    private overlay: Overlay,
    private _injector: Injector,
    private sanitizer: DomSanitizer,
    private ngZone: NgZone,
  ) {

    this.toastrConfig = {
      ...token?.default,
      ...token?.config,
    };
    if (token?.config?.iconClasses) {
      this.toastrConfig.iconClasses = {
        ...token?.default?.iconClasses,
        ...token?.config?.iconClasses,
      };
    }
  }

  showToastr(config: ToastrConfigModel): void {
    const opts: GlobalConfig = config.options ? Object.assign({}, config?.options) : this.toastrConfig
    const MsgType: string = config?.type ?? 'success'
    console.log(opts)
    this.show(config?.message, config?.title, opts, opts?.iconClasses[MsgType])
  }

  /** show toast */
  show(message?: string, title?: string, override: Partial<IndividualConfig> = {}, type = ''): ActiveToast<any> | null {
    return this._preBuildNotification(type, message, title, this.applyConfig(override));
  }
  /** show successful toast */
  success(message?: string, title?: string, override: Partial<IndividualConfig> = {}): ActiveToast<any> | null {
    const type: string = this.toastrConfig?.iconClasses?.success || '';
    return this._preBuildNotification(type, message, title, this.applyConfig(override));
  }
  /** show error toast */
  error(message?: string, title?: string, override: Partial<IndividualConfig> = {}): ActiveToast<any> | null {
    const type: string = this.toastrConfig?.iconClasses?.error || '';
    return this._preBuildNotification(type, message, title, this.applyConfig(override));
  }
  /** show info toast */
  info(message?: string, title?: string, override: Partial<IndividualConfig> = {}): ActiveToast<any> | null {
    const type: string = this.toastrConfig?.iconClasses?.info || '';
    return this._preBuildNotification(type, message, title, this.applyConfig(override));
  }
  /** show warning toast */
  warning(message?: string, title?: string, override: Partial<IndividualConfig> = {}): ActiveToast<any> | null {
    const type: string = this.toastrConfig?.iconClasses?.warning || '';
    return this._preBuildNotification(type, message, title, this.applyConfig(override));
  }
  /**
   * Remove all or a single toast by id
   */
  clear(toastId?: number): void {
    // Call every toastRef manualClose function
    for (const toast of this.toasts) {
      if (toastId !== undefined) {
        if (toast?.toastId === toastId) {
          toast?.toastRef?.manualClose();
          return;
        }
      } else {
        toast?.toastRef?.manualClose();
      }
    }
  }
  /**
   * Remove and destroy a single toast by id
   */
  remove(toastId: number): boolean {
    const found = this._findToast(toastId);
    if (!found) {
      return false;
    }
    found?.activeToast?.toastRef?.close();
    this.toasts?.splice(found.index, 1);
    this.currentlyActive = this.currentlyActive - 1;
    if (!this.toastrConfig?.maxOpened || !this.toasts?.length) {
      return false;
    }
    if (this.currentlyActive < this.toastrConfig?.maxOpened && this.toasts[this.currentlyActive]) {
      const p = this.toasts[this.currentlyActive]?.toastRef;
      if (!p.isInactive()) {
        this.currentlyActive = this.currentlyActive + 1;
        p.activate();
      }
    }
    return true;
  }

  /**
   * Determines if toast message is already shown
   */
  findDuplicate(title = '', message = '', resetOnDuplicate: boolean, countDuplicates: boolean): ActiveToast<any> | null {
    const { includeTitleDuplicates } = this.toastrConfig;

    for (const toast of this.toasts) {
      const hasDuplicateTitle: boolean = includeTitleDuplicates && toast.title === title;
      if ((!includeTitleDuplicates || hasDuplicateTitle) && toast?.message === message) {
        toast?.toastRef?.onDuplicate(resetOnDuplicate, countDuplicates);
        return toast;
      }
    }

    return null;
  }

  /** create a clone of global config and apply individual settings */
  private applyConfig(override: Partial<IndividualConfig> = {}): GlobalConfig {
    return { ...this.toastrConfig, ...override };
  }

  /**
   * Find toast object by id
   */
  private _findToast(toastId: number): { index: number; activeToast: ActiveToast<any> } | null {
    for (let i = 0; i < this.toasts?.length; i++) {
      if (this.toasts[i].toastId === toastId) {
        return { index: i, activeToast: this.toasts[i] };
      }
    }
    return null;
  }

  /**
   * Determines the need to run inside angular's zone then builds the toast
   */
  private _preBuildNotification(
    toastType: string,
    message: string | undefined,
    title: string | undefined,
    config: GlobalConfig,
  ): ActiveToast<any> | null {
    if (config.onActivateTick) {
      return this.ngZone.run(() => this._buildNotification(toastType, message, title, config));
    }
    return this._buildNotification(toastType, message, title, config);
  }

  /**
   * Creates and attaches toast data to component
   * returns the active toast, or in case preventDuplicates is enabled the original/non-duplicate active toast.
   */
  private _buildNotification(
    toastType: string,
    message: string | undefined,
    title: string | undefined,
    config: GlobalConfig,
  ): ActiveToast<any> | null {
    if (!config.toastComponent) {
      throw new Error('toastComponent required');
    }
    // max opened and auto dismiss = true
    // if timeout = 0 resetting it would result in setting this.hideTime = Date.now(). Hence, we only want to reset timeout if there is
    // a timeout at all
    const duplicate: ActiveToast<any> | null = this.findDuplicate(
      title,
      message,
      this.toastrConfig?.resetTimeoutOnDuplicate && config?.timeOut > 0,
      this.toastrConfig?.countDuplicates,
    );
    if (
      ((this.toastrConfig?.includeTitleDuplicates && title) || message) &&
      this.toastrConfig?.preventDuplicates &&
      duplicate !== null
    ) {
      return duplicate;
    }

    this.previousToastMessage = message;
    let keepInactive: boolean = false;
    if (this.toastrConfig?.maxOpened && this.currentlyActive >= this.toastrConfig?.maxOpened) {
      keepInactive = true;
      if (this.toastrConfig?.autoDismiss) {
        this.clear(this.toasts[0].toastId);
      }
    }

    const overlayRef: OverlayRef = this.overlay.create(config.positionClass, this.overlayContainer);
    this.index = this.index + 1;
    let sanitizedMessage: string | undefined | null = message;
    if (message && config?.enableHtml) {
      sanitizedMessage = this.sanitizer?.sanitize(SecurityContext.HTML, message);
    }

    const toastRef = new ToastRef(overlayRef);
    const toastPackage: ToastPackage = new ToastPackage(
      this.index,
      config,
      sanitizedMessage,
      title,
      toastType,
      toastRef,
    );
    const toastInjector: ToastInjector = new ToastInjector(toastPackage, this._injector);
    const component: ComponentPortal<any> = new ComponentPortal(config?.toastComponent, toastInjector);
    const portal: ComponentRef<any> = overlayRef.attach(component, this.toastrConfig?.newestOnTop);
    toastRef.componentInstance = portal?.instance;
    const ins: ActiveToast<any> = {
      toastId: this.index,
      title: title || '',
      message: message || '',
      toastRef,
      onShown: toastRef?.afterActivate(),
      onHidden: toastRef?.afterClosed(),
      onTap: toastPackage?.onTap(),
      onAction: toastPackage?.onAction(),
      portal,
    };

    if (!keepInactive) {
      this.currentlyActive = this.currentlyActive + 1;
      setTimeout(() => {
        ins.toastRef.activate();
      });
    }

    this.toasts.push(ins);
    return ins;
  }
}

