import moment from 'moment';
import { StringUtil } from './string.util';
export type DATE_FORMAT =
  | 'YYYY-MM-DD'
  | 'DD-MM-YYYY'
  | 'MM-DD-YYYY'
  | 'MMMM Do YYYY';
export interface CustomDateInterface {
  month: string |undefined;
  day: string;
  year: string;
}

export class DateUtil {
  static DEFAULT_DATE: CustomDateInterface = {
    year: 'YYYY',
    month: 'MM',
    day: 'DD',
  };
  static convertDateToCustomFormat(date: string | Date): string | undefined {
    if (!date) {
      return undefined;
    }
    const convertDate: CustomDateInterface = DateUtil.getCustomDateFormat(
      new Date(date)
    );
    return `${String(convertDate.day)}-${String(convertDate.month)}-${String(convertDate.year)}`;
  }
  static getCustomDateFormat(date: Date): CustomDateInterface {
    if (!date) {
      return DateUtil.DEFAULT_DATE;
    }
    return {
      day: DateUtil.covertToDigit(
        StringUtil.toNumberString(Number(DateUtil.getDay(date))) as string
      ) as string,
      month: DateUtil.covertToDigit(
        StringUtil.toNumberString(Number(DateUtil.getMonth(date)) )  as string
      ) ,
      year: StringUtil.toNumberString(DateUtil.getYear(date)) as string,
    };
  }

  static covertToDigit(day: string): string |undefined {
    if (day?.length <= 1) {
      return `0${day}`;
    }
    return day;
  }

  static getDay(date: Date): number| undefined {
    return date.getDate();
  }

  static getMonth(date: Date): number | undefined{
    return date.getMonth() + 1 ?? 0;
  }

  static getYear(date: Date): number {
    return date.getFullYear() ?? 0;
  }

  static format(
    date: Date | string,
    format: DATE_FORMAT = 'DD-MM-YYYY'
  ): string | undefined {
    if (!date) {
      return undefined;
    }
    return moment(date).format(format);
  }
  static fromNow(date: Date | string): string | undefined  {
    if (!date) {
      return undefined;
    }
    return moment(date).fromNow();
  }
}

import moment from 'moment';

export type DATE_FORMAT = 'YYYY-MM-DD' | 'YYYY/MM/DD' | 'YYYY/MM/dd' | 'MMMM YYYY' | 'DD/MM/YYYY' | 'YYYY/MM/DD HH:mm:ss'

export class DateUtil {
    static readonly DEFAULT_ISO_FORMAT: string = 'YYYY-MM-DD';
    static readonly DEFAULT_DISPLAY_FORMAT: string = 'YYYY/MM/DD';
    static readonly DEFAULT_PIPE_DISPLAY_FORMAT: string = 'YYYY/MM/dd';
    static readonly MONTH_YEAR_FORMAT: string = 'MMMM YYYY';
    static readonly DAY_MONTH_YEAR_FORMAT: string = 'DD/MM/YYYY';
    static readonly DEFAULT_DISPLAY_WITH_TIME_FORMAT: string = `${DateUtil.DEFAULT_DISPLAY_FORMAT} HH:mm:ss`;

    /**
     * Converts a date to a string date format.
     * @param date Date to format
     * @param format Date format based on momentjs's date format fields.
     *               If undefined, the ISO date will be used
     */
    static format(date: Date | string | moment.Moment | undefined, format: string = DateUtil.DEFAULT_ISO_FORMAT): string | undefined {
        return (date)
            ? moment(date)
                .format(format)
            : undefined;
    }

    static toMoment(value?: string | Date): moment.Moment {
        return moment(value);
    }


}

import {
  ApplicationRef,
  ComponentFactoryResolver,
  ComponentRef,
  EmbeddedViewRef,
} from '@angular/core';
import { BasePortalHost, ComponentPortal } from './portal';

/**
 * A PortalHost for attaching portals to an arbitrary DOM element outside of the Angular
 * application context.
 *
 * This is the only part of the portal core that directly touches the DOM.
 */
export class DomPortalHost extends BasePortalHost {
  constructor(
    private _hostDomElement: Element,
    private _componentFactoryResolver: ComponentFactoryResolver,
    private _appRef: ApplicationRef,
  ) {
    super();
  }

  /**
   * Attach the given ComponentPortal to DOM element using the ComponentFactoryResolver.
   * @param portal Portal to be attached
   */
  attachComponentPortal<T>(
    portal: ComponentPortal<T>,
    newestOnTop: boolean,
  ): ComponentRef<T> {
    const componentFactory = this._componentFactoryResolver.resolveComponentFactory(
      portal.component,
    );
    let componentRef: ComponentRef<T>;

    // If the portal specifies a ViewContainerRef, we will use that as the attachment point
    // for the component (in terms of Angular's component tree, not rendering).
    // When the ViewContainerRef is missing, we use the factory to create the component directly
    // and then manually attach the ChangeDetector for that component to the application (which
    // happens automatically when using a ViewContainer).
    componentRef = componentFactory.create(portal.injector);

    // When creating a component outside of a ViewContainer, we need to manually register
    // its ChangeDetector with the application. This API is unfortunately not yet published
    // in Angular core. The change detector must also be deregistered when the component
    // is destroyed to prevent memory leaks.
    this._appRef.attachView(componentRef.hostView);

    this.setDisposeFn(() => {
      this._appRef.detachView(componentRef.hostView);
      componentRef.destroy();
    });

    // At this point the component has been instantiated, so we move it to the location in the DOM
    // where we want it to be rendered.
    if (newestOnTop) {
      this._hostDomElement.insertBefore(
        this._getComponentRootNode(componentRef),
        this._hostDomElement.firstChild,
      );
    } else {
      this._hostDomElement.appendChild(
        this._getComponentRootNode(componentRef),
      );
    }

    return componentRef;
  }

  /** Gets the root HTMLElement for an instantiated component. */
  private _getComponentRootNode(componentRef: ComponentRef<any>): HTMLElement {
    return (componentRef.hostView as EmbeddedViewRef<any>).rootNodes[0] as HTMLElement;
  }
}

import { Component, Input, OnInit } from '@angular/core';

@Component({
  selector: 'dx-avatar',
  templateUrl: './dx-avatar.component.html',
  styleUrls: ['./dx-avatar.component.scss'],
})
export class DxAvatarComponent implements OnInit {
  @Input() val!: string;
  ngOnInit(): void {
    this.val = this.val ? this.getInitials(this.val) : '-';
  }

  getInitials = (name: string):string => {
    let initials:string[] | string | undefined= name?.split(' ');

    if (initials && initials?.length > 1) {
      initials = `${String(initials?.shift()?.charAt(0))}${String(initials?.pop()?.charAt(0))}`;
    } else {
      initials = name.substring(0, 2);
    }

    return initials.toUpperCase();
  };
}

