import { Source } from './source';
import { AvatarSource } from './avatar-source.enum';
/**
 *  Facebook source implementation.
 *  Fetch avatar source based on facebook identifier
 *  and image size
 */
export class Facebook implements Source {
  readonly sourceType: AvatarSource = AvatarSource.FACEBOOK;

  constructor(public sourceId: string) {}

  public getAvatar(size: number): string {
    return (
      'https://graph.facebook.com/' +
      `${this.sourceId}/picture?width=${size}&height=${size}`
    );
  }
}

import { AsyncSource } from './async-source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  GitHub source implementation.
 *  Fetch avatar source based on github identifier
 */
export class Github extends AsyncSource {
  readonly sourceType: AvatarSource = AvatarSource.GITHUB;

  constructor(sourceId: string) {
    super(sourceId);
  }

  public getAvatar(): string {
    return `https://api.github.com/users/${this.sourceId}`;
  }

  /**
   * extract github avatar from json data
   */
  public processResponse(data: { avatar_url: string }, size?: number): string {
    if (size) {
      return `${data.avatar_url}&s=${size}`;
    }
    return data.avatar_url;
  }
}

import { AsyncSource } from './async-source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  Google source implementation.
 *  Fetch avatar source based on google identifier
 *  and image size
 */
export class Google extends AsyncSource {
  readonly sourceType: AvatarSource = AvatarSource.GOOGLE;

  constructor(sourceId: string) {
    super(sourceId);
  }

  public getAvatar(): string {
    return `https://picasaweb.google.com/data/entry/api/user/${
      this.sourceId
    }?alt=json`;
  }

  /**
   * Extract google avatar from json data
   */
  public processResponse(data: { entry: { gphoto$thumbnail: { $t: string } } }, size?: number): string | null {
    const avatarSrc = data.entry.gphoto$thumbnail.$t;
    if (avatarSrc) {
      return avatarSrc.replace('s64', 's' + size);
    }

    return null;
  }
}

import { Source } from './source';
import { AvatarSource } from './avatar-source.enum';

/**
 * Initials source implementation.
 * return the initials of the given value
 */
export class Initials implements Source {
  readonly sourceType: AvatarSource = AvatarSource.INITIALS;

  constructor(public sourceId: string) {}

  public getAvatar(size: number): string {
    return this.getInitials(this.sourceId, size);
  }

  /**
   * Returns the initial letters of a name in a string.
   */
  private getInitials(name: string, size: number): string {
    name = name.trim();

    if (!name) {
      return '';
    }

    const initials = name.split(' ');

    if (size && size < initials.length) {
      return this.constructInitials(initials.slice(0, size));
    } else {
      return this.constructInitials(initials);
    }
  }

  /**
   * Iterates a person's name string to get the initials of each word in uppercase.
   */
  private constructInitials(elements: string[]): string {
    if (!elements || !elements.length) {
      return '';
    }

    return elements
      .filter(element => element && element.length > 0)
      .map(element => element[0].toUpperCase())
      .join('');
  }
}

import { AsyncSource } from './async-source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  Instagram source impelementation.
 *  Fetch avatar source based on instagram identifier
 */
export class Instagram extends AsyncSource {
  readonly sourceType: AvatarSource = AvatarSource.INSTAGRAM;

  constructor(sourceId: string) {
    super(sourceId);
  }

  public getAvatar(): string {
    return `https://www.instagram.com/${this.sourceId}/?__a=1`;
  }

  /**
   * extract instagram avatar from json data
   */
  public processResponse(data: { graphql: { user: { profile_pic_url_hd: string } } }, size?: number): string {
    return `${data.graphql.user.profile_pic_url_hd}&s=${size}`;
  }
}

