import { Menu, MenuModule, SubMenu, SubMenuModule } from '../../model/menu';

export class MenuTransform {
  static MENU_SEQ: { menu: string; order: number; }[] = [
    {
      menu: 'HOME',
      order: 1
    },
    {
      menu: 'PAYMENT',
      order: 3
    },
    {
      menu: 'QUOTE',
      order: 2
    },
    {
      menu: 'POLICY',
      order: 4
    },
    {
      menu: 'REPORTS',
      order: 5
    },
    {
      menu: 'SETTINGS',
      order: 6
    }
  ];
  static PAYMENT_SEQ: { menu: string; order: number; icon: string, name: string }[] = [
    {
      menu: 'COLLECTION',
      order: 4,
      icon: 'credit_score',
      name: 'Payments Desk'
    },
    {
      menu: 'ADDPAYMENT',
      order: 1,
      icon: 'account_balance_wallet',
      name: 'Add Payments'
    },
    {
      menu: 'VERIFYPAYMENT',
      order: 2,
      icon: 'assignment_turned_in',
      name: 'Verify Payments'
    },
    {
      menu: 'PAYINSLIP',
      order: 3,
      icon: 'receipt',
      name: 'Paying-in-Slip'
    }
  ];
  static transform(src: MenuModule[]): Menu[] {
    const home: Menu[] = [
      {
        label: 'Home',
        code: 'HOME',
        icon: 'home',
        active: true,
        route: {
          path: '/home',
          param: undefined,
        },
      },
    ];
    return [
      ...home,
      ...src?.map((menu: MenuModule) => {
        return {
          label: menu.menuLabel,
          icon: menu.menuIcon,
          code: menu.menu,
          order: MenuTransform.MENU_SEQ.find((data) => data?.menu === menu?.menu)?.order,
          children: MenuTransform.subMenuTransform(menu, menu?.submenu!),
          route: {
            path: menu?.path,
            param: undefined,
          },
        };
      }),
    ].sort(
      (a: Menu, b: Menu) => Number(a?.order) - Number(b?.order));
  }
  static subMenuTransform(
    parentSrc: MenuModule,
    child: SubMenuModule[]
  ): SubMenu[] {
    let subPayment: SubMenu[] | any | undefined = child?.map((ch: SubMenuModule) => {
      return {
        parentId: parentSrc?.menu,
        parentName: parentSrc?.menuLabel,
        label: ch?.subMenuLabel,
        icon: ch?.subMenuIcon,
        code: ch?.subMenuName,
        route: {
          path: ch?.path,
        },
      };
    });

    if (parentSrc.menu === 'PAYMENT') {
      subPayment = subPayment?.map((sub: SubMenu) => {
        return {
          ...sub,
          order: MenuTransform.PAYMENT_SEQ.find((data) => data?.menu === sub?.code)?.order,
          icon: MenuTransform.PAYMENT_SEQ.find((data) => data?.menu === sub?.code)?.icon,
          label: MenuTransform.PAYMENT_SEQ.find((data) => data?.menu === sub?.code)?.name
        }
      }).sort(
        (a: Menu, b: Menu) => Number(a?.order) - Number(b?.order));
      const index: number = subPayment?.findIndex((sub: SubMenu) => sub?.code === 'PAYFORT');
      subPayment.splice(index, 1);
    }

    return subPayment;
  }
}

