export class MethodMention {
  static attachDataValues(element: any, data: any, dataAttributes:any) {
    const mention = element;
    Object.keys(data).forEach(key => {
      if (dataAttributes.indexOf(key) > -1) {
        mention.dataset[key] = data[key];
      } else {
        delete mention.dataset[key];
      }
    });
    return mention;
  }
  
  static getMentionCharIndex(text: any, mentionDenotationChars: any) {
    return mentionDenotationChars.reduce(
      (prev: any, mentionChar: any) => {
        const mentionCharIndex = text.lastIndexOf(mentionChar);
  
        if (mentionCharIndex > prev.mentionCharIndex) {
          return {
            mentionChar,
            mentionCharIndex
          };
        }
        return {
          mentionChar: prev.mentionChar,
          mentionCharIndex: prev.mentionCharIndex
        };
      },
      { mentionChar: null, mentionCharIndex: -1 }
    );
  }
  
  static hasValidChars(text: any, allowedChars: any) {
    return allowedChars.test(text);
  }
  
  static hasValidMentionCharIndex(mentionCharIndex: any, text: any, isolateChar: any) {
    if (mentionCharIndex > -1) {
      if (
        isolateChar &&
        !(mentionCharIndex === 0 || !!text[mentionCharIndex - 1].match(/\s/g))
      ) {
        return false;
      }
      return true;
    }
    return false;
  }
  
}

import { ComponentRef } from '@angular/core';
import { BasePortalHost, ComponentPortal } from '../portal/portal';

/**
 * Reference to an overlay that has been created with the Overlay service.
 * Used to manipulate or dispose of said overlay.
 */
export class OverlayRef {
  constructor(private _portalHost: BasePortalHost) { }


  // we need to pass component for ComponentPortal<any>,currently we dont have  interface for component.
  attach(
    portal: ComponentPortal<any>,
    newestOnTop: boolean = true,
  ): ComponentRef<any> {
