import Quill from 'quill';
import { EmailDropdown, videoPlayerDataModel } from './model/quill.model';

// Add a custom DropDown Menu to the Quill Editor's toolbar:
declare const QuillToolbarDropDown: any;
declare const QuillToolbarButton: any;
export class QuillCustomButtons {
  public static addEmailDropdown(quill: Quill, emailConfig: EmailDropdown) {
    const dropDownItems = emailConfig.emails;

    const myDropDown: any = new QuillToolbarDropDown({
      label: emailConfig.label ?? 'Email Address',
      rememberSelection: false,
    });

    myDropDown.setItems(dropDownItems);

    myDropDown.onSelect = function (label: any, value: any, quill: any) {
      // Do whatever you want with the new dropdown selection here
      // For example, insert the value of the dropdown selection:
      const { index, length } = quill.selection.savedRange;
      quill.deleteText(index, length);
      quill.insertText(index, value);
      quill.setSelection(index + value.length);
      console.log(value, quill);
    };

    myDropDown.attach(quill);
  }

  public static convertTextToUpperCase(quill: Quill) {
    const myButton = new QuillToolbarButton({
      icon: `<svg viewBox="0 0 18 18"> <path class="ql-stroke" d="M5,3V9a4.012,4.012,0,0,0,4,4H9a4.012,4.012,0,0,0,4-4V3"></path></svg>`,
    });
    myButton.onClick = function (quill: any) {
      // Do whatever you want here. You could use this.getValue() or this.setValue() if you wanted.
      // For example, get the selected text and convert it to uppercase:
      const { index, length } = quill.selection.savedRange;
      const selectedText = quill.getText(index, length);
      const newText = selectedText.toUpperCase();
      quill.deleteText(index, length);
      quill.insertText(index, newText);
      quill.setSelection(index, newText.length);
    };
    myButton.attach(quill);
  }

  public static addDxVideoPlayer(quill: Quill) {
    const myVideoPlayer = new QuillToolbarButton({
      icon: `<svg xmlns="http://www.w3.org/2000/svg" height="24px" viewBox="0 0 24 24" width="24px" fill="#000000"><path d="M0 0h24v24H0V0z" fill="none"/><path d="M15 8v8H5V8h10m1-2H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4V7c0-.55-.45-1-1-1z"/></svg>`,
    });
    let playerIndex: number = 0;
    myVideoPlayer.onClick = function (quill: any) {
      const { index, length } = quill.selection.savedRange;

      var videoPlayer = prompt('Video Url');
      if (videoPlayer) {
        const payload: videoPlayerDataModel = {
          value: videoPlayer,
          playerIndex: playerIndex,
        };
        quill.insertEmbed(index, 'videoPlayer', payload);
        playerIndex++;
        quill.deleteText(index, length);
      }
    };
    myVideoPlayer.attach(quill);
  }
}

