import { Injector, InjectFlags } from '@angular/core';
import { Observable, Subject } from 'rxjs';
import { OverlayRef } from '../overlay/overlay-ref';
import { ToastPackage } from './toastr-config';

/**
 * Reference to a toast opened via the Toastr service.
 */
export class ToastRef<T> {
  /** The instance of component opened into the toast. */
  componentInstance!: T;

  /** Count of duplicates of this toast */
  private duplicatesCount = 0;

  /** Subject for notifying the user that the toast has finished closing. */
  private _afterClosed = new Subject<void>();
  /** triggered when toast is activated */
  private _activate = new Subject<void>();
  /** notifies the toast that it should close before the timeout */
  private _manualClose = new Subject<void>();
  /** notifies the toast that it should reset the timeouts */
  private _resetTimeout = new Subject<void>();
  /** notifies the toast that it should count a duplicate toast */
  private _countDuplicate = new Subject<number>();

  constructor(private _overlayRef: OverlayRef) { }

  manualClose(): void {
    this._manualClose?.next();
    this._manualClose?.complete();
  }

  manualClosed(): Observable<void> {
    return this._manualClose?.asObservable();
  }

  timeoutReset(): Observable<void> {
    return this._resetTimeout?.asObservable();
  }

  countDuplicate(): Observable<number> {
    return this._countDuplicate?.asObservable();
  }

  /**
   * Close the toast.
   */
  close(): void {
    this._overlayRef?.detach();
    this._afterClosed?.next();
    this._manualClose?.next();
    this._afterClosed?.complete();
    this._manualClose?.complete();
    this._activate?.complete();
    this._resetTimeout?.complete();
    this._countDuplicate?.complete();
  }

  /** Gets an observable that is notified when the toast is finished closing. */
  afterClosed(): Observable<void> {
    return this._afterClosed?.asObservable();
  }

  isInactive(): boolean {
    return this._activate?.isStopped;
  }

  activate(): void {
    this._activate?.next();
    this._activate?.complete();
  }

  /** Gets an observable that is notified when the toast has started opening. */
  afterActivate(): Observable<void> {
    return this._activate.asObservable();
  }

  /** Reset the toast timouts and count duplicates */
  onDuplicate(resetTimeout: boolean, countDuplicate: boolean): void {
    if (resetTimeout) {
      this._resetTimeout?.next();
    }
    if (countDuplicate) {
      this._countDuplicate?.next(++this.duplicatesCount);
    }
  }
}

/** Custom injector type specifically for instantiating components with a toast. */
export class ToastInjector implements Injector {
  constructor(
    private _toastPackage: ToastPackage,
    private _parentInjector: Injector
  ) { }

  get<T>(token: any, notFoundValue?: T, flags?: InjectFlags): T | ToastPackage {
    if (token === ToastPackage) {
      return this._toastPackage;
    }
    return this._parentInjector?.get<T>(token, notFoundValue, flags);
  }
}

import { BehaviorSubject } from "rxjs";
import { TREE_MODEL, ItemNode } from "./tree.model";

/**
 * Checklist database, it can build a tree structured Json object.
 * Each node in Json object represents a to-do item or a category.
 * If a node is a category, it has children items and new items can be added under the category.
 */
export class TreeUtil<T> {
    TREE_DATA!: TREE_MODEL<T>[];
    dataChange: BehaviorSubject<ItemNode<T>[]> = new BehaviorSubject<ItemNode<T>[]>([]);

    get data(): ItemNode<T>[] { return this.dataChange?.value; }

    constructor(private readonly payload: TREE_MODEL<T>[]) {
        if (payload) {
            this.initialize(payload);
        }
    }

    initialize(payload: TREE_MODEL<T>[]): void {
        // Build the tree nodes from Json object. The result is a list of `ItemNode<T>` with nested
        //     file node as children.
        const data: ItemNode<T>[]
            = this.buildFileTree(payload, 0);
        // Notify the change.
        this.dataChange?.next(data);
    }

    /**
     * Build the file structure tree. The `value` is the Json object, or a sub-tree of a Json object.
     * The return value is the list of `ItemNode<T>`.
     */
    buildFileTree(arr: TREE_MODEL<T>[], level: number): ItemNode<T>[] {
        return arr?.reduce<ItemNode<T>[]>((accumulator: ItemNode<T>[], currentValue: TREE_MODEL<T>) => {
            const obj: TREE_MODEL<T> = currentValue;
            const node: ItemNode<T> = new ItemNode<T>();
            node.item = obj?.labelTt;
            node.data = obj
            if (obj?.children) {
                node.children = this.buildFileTree(obj?.children, level + 1);
            }
            return accumulator?.concat(node);
        }, []);
    }

    /** Add an item to to-do list */
    insertItem(parent: ItemNode<T>, name: string): ItemNode<T> {
        if (!parent?.children) {
            parent.children = [];
        }
        const newItem: ItemNode<T> = { item: name } as ItemNode<T>;
        parent?.children?.push(newItem);
        this.dataChange?.next(this.data);
        return newItem;
    }

    insertItemAbove(node: ItemNode<T>, name: string): ItemNode<T> {
        const parentNode: ItemNode<T> | null = this.getParentFromNodes(node);
        const newItem: ItemNode<T> = { item: name } as ItemNode<T>;
        if (parentNode) {
            parentNode?.children?.splice(parentNode?.children?.indexOf(node), 0, newItem);
        } else {
            this.data?.splice(this.data?.indexOf(node), 0, newItem);
        }
        this.dataChange?.next(this.data);
        return newItem;
    }

    insertItemBelow(node: ItemNode<T>, name: string): ItemNode<T> {
        const parentNode: ItemNode<T> | null = this.getParentFromNodes(node);
        const newItem: ItemNode<T> = { item: name } as ItemNode<T>;
        if (parentNode) {
            parentNode?.children?.splice(parentNode?.children?.indexOf(node) + 1, 0, newItem);
        } else {
            this.data?.splice(this.data?.indexOf(node) + 1, 0, newItem);
        }
        this.dataChange?.next(this.data);
        return newItem;
    }

    getParentFromNodes(node: ItemNode<T>): ItemNode<T> | null {
        for (let i = 0; i < this.data.length; ++i) {
            const currentRoot: ItemNode<T> = this.data[i];
            const parent: ItemNode<T> | null = this.getParent(currentRoot, node);
            if (parent) {
                return parent;
            }
        }
        return null;
    }

    getParent(currentRoot: ItemNode<T>, node: ItemNode<T>): ItemNode<T> | null {
        if (currentRoot?.children && currentRoot?.children.length > 0) {
            for (let i = 0; i < currentRoot?.children?.length; ++i) {
                const child: ItemNode<T> = currentRoot?.children[i];
                if (child === node) {
                    return currentRoot;
                } else if (child?.children && child?.children?.length > 0) {
                    const parent: ItemNode<T> | null = this.getParent(child, node);
                    if (parent) {
                        return parent;
                    }
                }
            }
        }
        return null;
    }

    updateItem(node: ItemNode<T>, name: string): void {
        node.item = name;
        this.dataChange?.next(this.data);
    }

    deleteItem(node: ItemNode<T>): void {
        this.deleteNode(this.data, node);
        this.dataChange?.next(this.data);
    }

    copyPasteItem(from: ItemNode<T>, to: ItemNode<T>): ItemNode<T> {
        const newItem: ItemNode<T> = this.insertItem(to, from?.item);
        if (from?.children) {
            from?.children?.forEach((child: ItemNode<T>) => {
                this.copyPasteItem(child, newItem);
            });
        }
        return newItem;
    }

    copyPasteItemAbove(from: ItemNode<T>, to: ItemNode<T>): ItemNode<T> {
        const newItem: ItemNode<T> = this.insertItemAbove(to, from?.item);
        if (from?.children) {
            from?.children?.forEach((child: ItemNode<T>) => {
                this.copyPasteItem(child, newItem);
            });
        }
        return newItem;
    }

    copyPasteItemBelow(from: ItemNode<T>, to: ItemNode<T>): ItemNode<T> {
        const newItem: ItemNode<T> = this.insertItemBelow(to, from?.item);
        if (from?.children) {
            from?.children?.forEach((child: ItemNode<T>) => {
                this.copyPasteItem(child, newItem);
            });
        }
        return newItem;
    }

    deleteNode(nodes: ItemNode<T>[], nodeToDelete: ItemNode<T>): void {
        const index: number = nodes?.indexOf(nodeToDelete, 0);
        if (index > -1) {
            nodes?.splice(index, 1);
        } else {
            nodes?.forEach((node: ItemNode<T>) => {
                if (node?.children && node?.children?.length > 0) {
                    this.deleteNode(node?.children, nodeToDelete);
                }
            });
        }
    }
}

import { Source } from './source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  Twitter source implementation.
 *  Fetch avatar source based on google identifier
 *  and image size
 */
export class Twitter implements Source {
  readonly sourceType: AvatarSource = AvatarSource.TWITTER;

  constructor(public sourceId: string) {}

  public getAvatar(size: number): string {
    const twitterImgSize = this.getImageSize(size);
    return `https://twitter.com/${
      this.sourceId
    }/profile_image?size=${twitterImgSize}`;
  }

  private getImageSize(size: number) {
    if (size <= 24) {
      return 'mini';
    }

    if (size <= 48) {
      return 'normal';
    }

    if (size <= 73) {
      return 'bigger';
    }

    return 'original';
  }
}

import { Source } from './source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  Value source implementation.
 *  return the value as avatar
 */
export class Value implements Source {
  readonly sourceType: AvatarSource = AvatarSource.VALUE;

  constructor(public sourceId: string) {}

  public getAvatar(): string {
    return this.sourceId;
  }
}

import { AsyncSource } from './async-source';
import { AvatarSource } from './avatar-source.enum';

/**
 *  Vkontakte source implementation.
 *  Fetch avatar source based on vkontakte identifier
 *  and image size
 */
const apiVersion = 5.8;

export class Vkontakte extends AsyncSource {
  readonly sourceType: AvatarSource = AvatarSource.VKONTAKTE;

  constructor(sourceId: string) {
    super(sourceId);
  }

  public getAvatar(size: number): string {
    const imgSize = this.getImageSize(size);
    return `https://api.vk.com/method/users.get?user_id=${
      this.sourceId
    }&v=${apiVersion}&fields=${imgSize}`;
  }

  /**
   * extract vkontakte avatar from json data
   */
  public processResponse(data: {
    response: {
      [key: string]: string;
    }[]
  }): string | null {
    // avatar key property is the size used to generate avatar url
    // size property is always the last key in the response object
    const sizeProperty = Object.keys(data['response'][0]).pop();
    if (!sizeProperty) {
      return null;
    }
    // return avatar src
    return data['response'][0][sizeProperty] || null;
  }

  /**
   * Returns image size related to vkontakte API
   */
  private getImageSize(size: number): string {
    if (size <= 50) {
      return 'photo_50';
    }

    if (size <= 100) {
      return 'photo_100';
    }

    if (size <= 200) {
      return 'photo_200';
    }

    return 'photo_max';
  }
}

