import { ValidatorModel } from './model/validator.model';

@Directive({
  selector: '[onlyAadharCardValidator]',
  providers: [
    {
      multi: true,
      useExisting: forwardRef(() => AadharCardValidator),
      provide: NG_VALIDATORS,
    },
  ],
})
export class AadharCardValidator implements Validator {
  /**
   * @description aadhar card should follow below point
   * @see It should have 12 digits.
   * @see It should not start with 0 and 1.
   * @see It should not contain any alphabet and special characters.
   * @see It should have white space after every 4 digits.
   */
  private static _AADHAR_REGEXP =
    /^[2-9]{1}[0-9]{3}\s{1}[0-9]{4}\s{1}[0-9]{4}$/;

  /**
   * @deprecated It will take controller and add the aadhar validation in controller
   * @example
   *        <input onlyAadharCardValidator type="text">
   *        <error *ngIf="controllerName.errors.aadharInValid">Error Message</error>
   * @param formController
   * @returns AbstractControl
   */
  validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && AadharCardValidator._matchPattern(control)) {
      return { aadharInValid: true };
    }
    return null;
  }
  /**
   * @description
   *        It will take controller and copy properties of controller,
   *        perform action and return the update controller.
   * @method validate
   * @param formController
   * @returns AbstractControl
   */
  static validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && AadharCardValidator._matchPattern(control)) {
      return { aadharInValid: true };
    }
    return null;
  }
  /**
   * @description It will take controller as argument and check value exist or not if value exist than it will check value match with pattern or not
   * @method _onlyAadharValidator
   * @param formController
   * @returns boolean
   */
  private static _matchPattern(formController: AbstractControl): boolean {
    return !AadharCardValidator._AADHAR_REGEXP.test(formController.value);
  }
}

