@Directive({
  selector: '[addressValidator]',
  providers: [
    {
      multi: true,
      useExisting: forwardRef(() => AddressValidator),
      provide: NG_VALIDATORS,
    },
  ],
})
export class AddressValidator implements Validator {
  /**
   * @description You need not escape comma,single quote and hyphen.
   **  \w* match any word character [a-zA-Z0-9_]
   **   \s match any white space character [\r\n\t\f ]
   **  [\#\-\,\/\.\,\(\)\&]* match a single character present # - , . / ( ) &
   **  + Between one and unlimited times
   **  ^ assert position at start of the string
   **  * Between zero and unlimited time
   */
  private static readonly _ADDRESS_REGEXP: RegExp =
    /^(\w*\s*[\#\-\,\/\.\(\)\&]*)+$/;

  /**
   * @deprecated It will take controller and add the address validation in controller
   * @example
   *        <input addressValidator type="text">
   *        <error *ngIf="controllerName.errors.addressInValid">Error Message</error>
   * @param formController
   * @returns ValidatorModel | null
   */
  validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && AddressValidator._matchPattern(control)) {
      return { addressInValid: true };
    }
    return null;
  }
  /**
   * @description
   *        It will take controller and update controller controller,
   * @method validate
   * @param control
   * @returns ValidatorModel | null
   */
  static validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && AddressValidator._matchPattern(control)) {
      return { addressInValid: true };
    }
    return null;
  }
  /**
   * @description It will take controller as argument and check value exist or not if value exist than it will check value match with pattern or not
   * @method _matchPattern
   * @param control
   * @returns boolean
   */
  private static _matchPattern(control: AbstractControl): boolean {
    return !AddressValidator._ADDRESS_REGEXP.test(control.value);
  }
}

