import { Directive, forwardRef } from '@angular/core';
import { Validator, AbstractControl, NG_VALIDATORS } from '@angular/forms';
import { ValidatorModel } from './model/validator.model';

@Directive({
  selector: '[onlyVehicleChassisValidator]',
  providers: [
    {
      multi: true,
      useExisting: forwardRef(() => VehicleChassisValidator),
      provide: NG_VALIDATORS,
    },
  ],
})
export class VehicleChassisValidator implements Validator {
  private static _CHASSIS_REGEXP =
    /^(?=.*[0-9])(?=.*[a-z0-9A-Z])([a-zA-Z0-9]+){6,50}$/;
  /**
   * @deprecated It will take controller and add the chassis number validation in controller
   * @example
   *        <input onlyVehicleChassisValidator type="text">
   *        <error *ngIf="controllerName.errors.chassisNumberInValid">Error Message</error>
   * @param control
   * @returns ValidatorModel | null
   */
  validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && VehicleChassisValidator._matchPattern(control)) {
      return { invalidUniqueChar: true };
    }
    return null;
  }

  /**
   * @description
   *        It will take controller and update controller controller,
   * @method validate
   * @param control
   * @returns ValidatorModel | null
   */
  static validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && VehicleChassisValidator._matchPattern(control)) {
      return { invalidUniqueChar: true };
    }
    return null;
  }
  /**
   * @description It will take controller as argument and check value exist or not if value exist than it will check value match with pattern or not
   * @method _matchPattern
   * @param control
   * @returns boolean
   */
  private static _matchPattern(control: AbstractControl): boolean {
    return !VehicleChassisValidator._CHASSIS_REGEXP.test(control.value);
  }
}

