import { Directive, forwardRef } from '@angular/core';
import { Validator, AbstractControl, NG_VALIDATORS } from '@angular/forms';
import { ValidatorModel } from './model/validator.model';

@Directive({
  selector: '[onlyVehicleEngineNumberValidator]',
  providers: [
    {
      multi: true,
      useExisting: forwardRef(() => VehicleEngineNumberValidator),
      provide: NG_VALIDATORS,
    },
  ],
})
export class VehicleEngineNumberValidator implements Validator {
  private static _ENGINE_NUMBER_REGEXP =
    /^(?=.*[0-9])(?=.*[a-z0-9A-Z])([a-zA-Z0-9]+){6,50}$/;
  /**
   * @deprecated It will take controller and add the engine validation in controller
   * @example
   *        <input onlyVehicleEngineNumberValidator type="text">
   *        <error *ngIf="controllerName.errors.invalidEngineNumber">Error Message</error>
   * @param control
   * @returns ValidatorModel | null
   */
  validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && VehicleEngineNumberValidator._matchPattern(control)) {
      return { invalidEngineNumber: true };
    }
    return null;
  }

  /**
   * @description
   *        It will take controller and update controller controller,
