import { Directive, forwardRef } from '@angular/core';
import { Validator, AbstractControl, NG_VALIDATORS } from '@angular/forms';
import { ValidatorModel } from './model/validator.model';

@Directive({
  selector: '[onlyVehicleRegistrationValidator]',
  providers: [
    {
      multi: true,
      useExisting: forwardRef(() => VehicleRegistrationValidator),
      provide: NG_VALIDATORS,
    },
  ],
})
export class VehicleRegistrationValidator implements Validator {
  private static _REGISTRATION_REGEX =
    /^[A-Z]{2}[0-9]{1,2}(?:[A-Z])?(?:[A-Z]*)?[0-9]{1,4}$/;
  /**
   * @deprecated It will take controller and add the vehicle registration number validation in controller
   * @example
   *        <input onlyVehicleRegistrationValidator type="text">
   *        <error *ngIf="controllerName.errors.{ invalidVehicleNumber: true }">Error Message</error>
   * @param control
   * @returns ValidatorModel | null
   */
  validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && VehicleRegistrationValidator._matchPattern(control)) {
      return { invalidVehicleNumber: true };
    }
    return null;
  }

  /**
   * @description
   *        It will take controller and update controller controller,
   * @method validate
   * @param control
   * @returns ValidatorModel | null
   */
  static validate(control: AbstractControl): ValidatorModel | null {
    if (control.value && VehicleRegistrationValidator._matchPattern(control)) {
      return { invalidVehicleNumber: true };
    }
    return null;
  }
  /**
   * @description It will take controller as argument and check value exist or not if value exist than it will check value match with pattern or not
   * @method _matchPattern
   * @param control
   * @returns boolean
   */
  private static _matchPattern(control: AbstractControl): boolean {
    return !VehicleRegistrationValidator._REGISTRATION_REGEX.test(
      control.value
    );
  }
}

