@Component({
  selector: 'dx-currency',
  templateUrl: './currency.component.html',
  styleUrls: ['./currency.component.css'],
})
export class CurrencyComponent<T> implements OnChanges {
  static readonly DEFAULT_CURRENCY_CODE: string = '$ ';
  static readonly DEFAULT_DISPLAY: DisplayDigitsType = 'symbol';
  static readonly DEFAULT_DIGITS_INFO: string = '1.2-2';
  static readonly DEFAULT_LOCALE: string = 'en_in';

  @Input() amount!: number;
  @Input() currencyCode: string = CurrencyComponent.DEFAULT_CURRENCY_CODE;
  @Input() display: DisplayDigitsType = CurrencyComponent.DEFAULT_DISPLAY;
  @Input() digitsInfo: string = CurrencyComponent.DEFAULT_DIGITS_INFO;
  @Input() locale: string = CurrencyComponent.DEFAULT_LOCALE;
  @Input() column!: FlexTableColumn<T>;
  displayAmount!: number;
  displayCurrencyCode: string = CurrencyComponent.DEFAULT_CURRENCY_CODE;
  displayDisplay: 'code' | 'symbol' | 'symbol-narrow' =
    CurrencyComponent.DEFAULT_DISPLAY;
  displayDigitsInfo: string = CurrencyComponent.DEFAULT_DIGITS_INFO;
  displayLocale: string = CurrencyComponent.DEFAULT_LOCALE;
  copyText: string = 'Click to copy';

  ngOnChanges(_changes: SimpleChanges): void {
    this.displayAmount = this.amount;
    this.displayCurrencyCode = this.currencyCode
      ? this.currencyCode
      : CurrencyComponent.DEFAULT_CURRENCY_CODE;
    this.displayDisplay = this.display
      ? this.display
      : CurrencyComponent.DEFAULT_DISPLAY;
    this.displayDigitsInfo = this.digitsInfo
      ? this.digitsInfo
      : CurrencyComponent.DEFAULT_DIGITS_INFO;
    this.displayLocale = this.locale
      ? this.locale
      : CurrencyComponent.DEFAULT_LOCALE;
  }

  onClickCopy(): void {
    this.copyText = 'Copied';
  }
  changeText(): void {
    this.copyText = 'Click to copy';
  }
}

import { Component, Input } from '@angular/core';
import { DateUtil } from '../../../../utils/date/date.util';
import moment from 'moment';

@Component({
  selector: 'dx-date',
  templateUrl: './date.component.html',
  styleUrls: ['./date.component.css']
})
export class DateComponent {

  static readonly DEFAULT_FORMAT: string = DateUtil.DEFAULT_DISPLAY_FORMAT;
  static readonly DEFAULT_TEXT: string = '-';

  text: string = DateComponent.DEFAULT_TEXT;

  private _date!: Date | string;
  private _format: string = DateComponent.DEFAULT_FORMAT;
  private _defaultText: string = DateComponent.DEFAULT_TEXT;

  @Input()
  set date(val: string | Date) {
    
      if (this._date !== val) {
          this._date = val;
          this.updateText();
      }
  }

  get date(): string | Date {
      return this._date;
  }

  @Input()
  set format(val: string) {
      if (this._format !== val) {
          this._format = val;
          this.updateText();
      }
  }

  get format(): string {
      return this._format;
  }

  @Input()
  set defaultText(val: string) {
      if (this._defaultText !== val) {
          this._defaultText = val;
          this.updateText();
      }
  }

  get defaultText(): string {
      return this._defaultText;
  }

  private updateText(): void {
      const tmpFormat: string = this.format
          ? this.format
          : DateComponent.DEFAULT_FORMAT;
      this.text = this.date
          ? moment(this.date)
              .format(tmpFormat)
          : this.defaultText;
  }

}

