import { Component, Input, OnInit } from '@angular/core';

@Component({
  selector: 'dx-avatar',
  templateUrl: './dx-avatar.component.html',
  styleUrls: ['./dx-avatar.component.scss'],
})
export class DxAvatarComponent implements OnInit {
  @Input() val!: string;
  ngOnInit(): void {
    this.val = this.val ? this.getInitials(this.val) : '-';
  }

  getInitials = (name: string):string => {
    let initials:string[] | string | undefined= name?.split(' ');

    if (initials && initials?.length > 1) {
      initials = `${String(initials?.shift()?.charAt(0))}${String(initials?.pop()?.charAt(0))}`;
    } else {
      initials = name.substring(0, 2);
    }

    return initials.toUpperCase();
  };
}

export default class DxAvatar {
}

