  styleUrls: ['./dx-datepicker.component.scss'],
  providers: [
    {
      provide: DateAdapter,
      useClass: MomentDateAdapter,
      deps: [MAT_DATE_LOCALE, MAT_MOMENT_DATE_ADAPTER_OPTIONS],
    },

    { provide: MAT_DATE_FORMATS, useValue: FORMATS },
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => DxDatepickerComponent),
      multi: true,
    },
  ],
  encapsulation: ViewEncapsulation.None,
})
export class DxDatepickerComponent<D> implements ControlValueAccessor {
  @Input() maxDate!: Date;
  @Input() minDate!: Date;
  @Input() disabled: boolean = false;
  @Input() required!: boolean;
  @Output() onDateChange: EventEmitter<DatePickerModel<D>> = new EventEmitter<DatePickerModel<D>>();
  value: string = '';

  onChange: Function = () => { };
  onTouched: Function = () => { };

  inputChange(event: string): void {
    this.value = event;
    this.onChange(this.value);
  }

  writeValue(value: string): void {
    this.value = value;
  }

  registerOnChange(fn: Function): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: Function): void {
    this.onTouched = fn;
  }

  setDisabledState?(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }
  dateChange(evtName: string, evt: MatDatepickerInputEvent<D>): void {
    const payload: DatePickerModel<D> = {
      name: evtName,
      data: evt,
    };
    this.onDateChange.emit(payload);
  }
}

