  ngOnInit(): void {
    this.mobileScreenWidthChecker(screen.width);
    fromEvent(window, 'resize').subscribe((e: any) => {
      this.mobileScreenWidthChecker(e.target.innerWidth);
    });
  }
  mobileScreenWidthChecker(width: number) {
    if (width <= 767) {
      this.isMobileScreen = true;
    } else {
