import { AfterViewInit, Component, EventEmitter, Input, OnInit, Output, ViewChild } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatTabChangeEvent, MatTabGroup } from '@angular/material/tabs';
import { Observable, of } from 'rxjs';
import { NgDxAvatarSettings } from '../../core/UI/core/avatar/model/avatar';
import { DateAgoPipe } from '../../utils';
import { DxTabViewComponent } from '../dx-tab-view';
import { DefaultCompany } from './company-logo';
import { Company, HeaderIcons, Notifications, ProfileMenuDropdown, ReadNotification, TopBarSettings, UserDetails } from './header-model/model';

@Component({
  selector: 'dx-header',
  templateUrl: './dx-header.component.html',
  styleUrls: ['./dx-header.component.scss'],
  providers: [DateAgoPipe]
})
export class DxHeaderComponent implements OnInit, AfterViewInit {
  @ViewChild('matTabGroup') matTabGroup!: MatTabGroup
  @Input() isBusy$!: Observable<boolean>
  @Input() company!: Company
  @Input() topBarNotificationData!: Notifications | undefined
  @Input() headerIcons!: HeaderIcons[]
  @Input() currentUser!: UserDetails
  @Input() latestNotificationCount: number = 0;
  @Input() unReadNotificationCount: number = 1;
  @Input() profileMenuDropdown!: ProfileMenuDropdown
  @Output() onClickProfileMenu: EventEmitter<string> = new EventEmitter<string>();
  @Output() onClickIcons: EventEmitter<string> = new EventEmitter<string>();
  @Output() onSearchValueChange: EventEmitter<string> = new EventEmitter<string>();
  @Output() onSearchBarClose: EventEmitter<void> = new EventEmitter<void>();
  @Output() onOpenNotificationMenu: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Output() onCloseNotificationMenu: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Output() onClickMarkAllasRead: EventEmitter<void> = new EventEmitter<void>();
  @Output() onNotificationTabChange: EventEmitter<MatTabChangeEvent> = new EventEmitter<MatTabChangeEvent>();
  @Output() onReadNotification: EventEmitter<ReadNotification> = new EventEmitter<ReadNotification>();
  @Output() onClickLoadMore: EventEmitter<void> = new EventEmitter<void>();
  @Input() topBarSettings: TopBarSettings = {
    isSearchVisible: true,
    isCompanyVisible: true,
    isMenuVisible: false,
    isNotificationVisible: true,
    isProfileVisible: true,
  };
  @Input() topBarCompanyData: any[] = [];
  defaultLogo: string = DefaultCompany.logo
  avatarSettings: NgDxAvatarSettings = {
    size: 40,
    initialsSize: 2
  }
  logoAvatarSettings: NgDxAvatarSettings = {
    size: 50,
    initialsSize: 2,

  }
  notificationSettings: NgDxAvatarSettings = {
    size: 35,
    initialsSize: 2
  }
  NotificationLoader$!: Observable<boolean>

  isSearchFormVisible: boolean = false;
  searchForm: FormGroup = new FormGroup({
    searchField: new FormControl(),
  });


  isNotificationMenuOpened!: boolean;
  initialNotifyTrigger: any = 0;
  notificationIndex = 0;
  unReadToggleFg = new FormGroup({
    unread: new FormControl(false)
  })
  copyNotifications: Notifications | undefined;
  constructor() { }
  ngOnInit(): void {
    this.copyNotifications = this.topBarNotificationData
    this.showUnread()
  }
  ngAfterViewInit(): void {
    if (this.matTabGroup) {
      this.matTabGroup.selectedIndex = this.notificationIndex
    }
    setTimeout(() => {
      this.matTabGroup?.realignInkBar()
    }, 2000)

  }
  getUserName(): string {
    return this.currentUser ? this.currentUser?.firstName + ' ' + this.currentUser?.lastName : '-'
  }
  // show or hide search form
  showSearchForm(): void {
    this.searchForm.reset();
    var search: HTMLElement | null = document?.getElementById('searchField');
    if (search != null) {
      setTimeout(() => search?.focus(), 0);
    }
    this.isSearchFormVisible = !this.isSearchFormVisible;
    if (!this.isSearchFormVisible) {
      this.onSearchBarClose?.emit()
    }
  }

  matMenuTrigger(d: boolean): void {
    this.onOpenNotificationMenu.emit(d)
  }
  isClosed(): void {
    this.onCloseNotificationMenu.emit(true)
  }
  markAllAsRead(): void {
    this.onClickMarkAllasRead.emit()
  }
  loadMore() {
    this.onClickLoadMore.emit()
  }



  tabChanged(tabChangeEvent: MatTabChangeEvent): void {
    this.onNotificationTabChange.emit(tabChangeEvent)
  }
  readNotification(
    id: number,
    groupName: string,
    isRead: boolean
  ): void {
    const payload: ReadNotification = {
      id: id,
      groupName: groupName,
      isRead: isRead
    }
    this.onReadNotification.emit(payload)
  }
  profileMenuClicked(event: string): void {
    this.onClickProfileMenu.emit(event)
  }
  onClickIcon(event: string): void {
    this.onClickIcons.emit(event)
  }
  onSearchInputChange(event: Event): void {
    const target: HTMLInputElement = event?.target as HTMLInputElement;
    this.onSearchValueChange?.emit(target?.value)
  }
  showUnread(): void {
    this.unReadToggleFg?.controls?.unread?.valueChanges?.subscribe((data: boolean) => {
      if (data) {
        this.topBarNotificationData = this.topBarNotificationData?.map(item => {
          return {
            ...item,
            groupList: item.groupList?.filter(data => !data.isRead)
          }
        })
      } else {
        this.topBarNotificationData = this.copyNotifications
      }

    })
  }

}

