import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewChild,
} from '@angular/core';
import 'quill-emoji';
import { Mention } from '../../nested-quill-mention/main-index'; //replace this import with nested mention once build issue is fixed
Quill.register('modules/mention', Mention);
import Quill from 'quill';
import BlotFormatter from 'quill-blot-formatter';
import {
  customButtonConfigModel,
  QuillConfigModel,
  videoPlayerDataModel,
} from '../../model/quill.model';
import {
  ContentChange,
  EditorChangeContent,
  EditorChangeSelection,
  QuillEditorComponent,
  SelectionChange,
} from '../../quill-editor.component';
import { QuillCustomButtons } from '../../dx-custom-quill-buttons';
Quill.register('modules/blotFormatter', BlotFormatter);
//dx-video-player
var Embed = Quill.import('blots/embed');
class QuillVideoPlayer extends Embed {
  static create(videoPlayer: videoPlayerDataModel) {
    let node = super.create(videoPlayer.value);
    node.innerHTML = `<div style="width:425px"><dx-video-player id="video-player-item-${videoPlayer.playerIndex}" src="${videoPlayer.value}" (playerstared)="playerstared($event)" (playerended)="videoEnded($event)"></dx-video-player></div>`;
    return node;
  }
}
QuillVideoPlayer.blotName = 'videoPlayer';
QuillVideoPlayer.tagName = 'div';
Quill.register({
  'formats/videoPlayer': QuillVideoPlayer,
});
@Component({
  selector: 'dx-quill-editor',
  templateUrl: './dx-quill-editor.component.html',
  styleUrls: ['./dx-quill-editor.component.scss'],
})
export class DxQuillEditorComponent implements OnInit {
  htmlText = '';
  @ViewChild('editor') editor!: QuillEditorComponent;
  @Input() placeholder!: string;
  @Input() quillConfig!: QuillConfigModel;
  @Input() imageResize!: boolean;
  @Input() styles!: Object;
  @Input() customButtonsConfig!: customButtonConfigModel;
  @Input() setContent: string = '';
  @Output() ContentChanged: EventEmitter<ContentChange> =
    new EventEmitter<ContentChange>();
  @Output() changedEditor: EventEmitter<
    EditorChangeContent | EditorChangeSelection
  > = new EventEmitter<EditorChangeContent | EditorChangeSelection>();
  @Output() editorCreated: EventEmitter<Quill> = new EventEmitter<Quill>();
  @Output() blur: EventEmitter<string> = new EventEmitter<string>();
  @Output() focus: EventEmitter<string> = new EventEmitter<string>();
  constructor(private readonly cd: ChangeDetectorRef) {}

  ngOnInit() {
    if (this.imageResize) {
      this.quillConfig.blotFormatter = {};
    }
    setTimeout(() => {
      this.editor?.writeValue(this.setContent);
      this.cd?.detectChanges();
    }, 300);
  }
  onSelectionChanged = (event: SelectionChange) => {
    if (event.oldRange == null) {
      this.onFocus();
    }
    if (event.range == null) {
      this.onBlur();
    }
  };

  onContentChanged = (event: ContentChange) => {
    this.ContentChanged.emit(event);
  };

  onFocus = () => {
    this.focus.emit('focus');
  };
  onBlur = () => {
    this.blur.emit('blur');
  };
  onChangedEditor(event: EditorChangeContent | EditorChangeSelection) {
    this.changedEditor.emit(event);
  }
  created(event: Quill) {
    this.newCustomButtons(event);
    this.editorCreated.emit(event);
  }
  newCustomButtons(quill: Quill) {
    if (this.customButtonsConfig?.customButtons['dx-video-player']) {
      QuillCustomButtons.addDxVideoPlayer(quill);
    }
    if (this.customButtonsConfig?.customButtons['upper-case']) {
      QuillCustomButtons.convertTextToUpperCase(quill);
    }
    if (this.customButtonsConfig?.customButtons['email-dropdown']) {
      QuillCustomButtons.addEmailDropdown(
        quill,
        this.customButtonsConfig?.customButtons['email-dropdown']
      );
    }
  }
  videoStaredPlaying(event: any) {
    console.log('quill', event);
  }
  videoEnded(event: any) {
    console.log('quill', event);
  }
}

