import { trigger, state, style, transition, animate } from '@angular/animations';
import { Component, Input, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { of } from 'rxjs';
import { Observable } from 'rxjs/internal/Observable';
import { first } from 'rxjs/operators';
import { ActiveMenu, Menu, SubMenu, SUB_MENU_TYPE } from './model';
import { NgDxLayoutService } from './store/service/layout.service';

@Component({
  selector: 'dx-side-bar',
  templateUrl: './dx-side-bar.component.html',
  styleUrls: ['./dx-side-bar.component.scss'],
  animations: [
    trigger('slideInOut', [
      state(
        'in',
        style({
          height: '*',
          width: '240px',
        })
      ),
      state(
        'out',
        style({
          width: '0px', // new change
        })
      ),
      transition('in => out', animate('400ms ease-in-out')),
      transition('out => in', animate('400ms ease-in-out')),
    ]),
    trigger('slideInOutTwo', [
      state(
        'in',
        style({
          opacity: 1,
        })
      ),
      state(
        'out',
        style({
          opacity: 0,
        })
      ),
      transition('in => out', animate('400ms ease-in-out')),
      transition('out => in', animate('400ms ease-in-out')),
    ]),
    trigger('rotatedState', [
      state('in', style({ transform: 'rotate(0)' })),
      state('out', style({ transform: 'rotate(-180deg)' })),
      transition('out => in', animate('400ms ease-out')),
      transition('in => out', animate('400ms ease-in')),
    ]),
  ],
})
export class DxSideBarComponent implements OnInit {
  @Input() logo: any;
  subMenu$!: Observable<SUB_MENU_TYPE>;
  menu$!: Observable<Menu[]> | any;
  activeMenu$!: Observable<ActiveMenu>;
  subMenuList$!: Observable<SubMenu[]> | any;

  constructor(
    private readonly layoutService: NgDxLayoutService,
    private readonly route: Router,


  ) { }

  ngOnInit(): void {
    this.subMenu$ = this.layoutService.getSubOpen();
    this.menu$ = this.layoutService.getMenu();
    this.subMenuList$ = this.layoutService.getSubMenu();
    this.activeMenu$ = this.layoutService.getActiveMenu();
  }


  onMenu(code: Menu): void {
    if (code.route && code?.route?.path) {
      this.route?.navigate([code?.route?.path], {
        queryParams: code?.route?.param,
      });
    }
    this.layoutService.setActiveMenu(code);
  }
  onSubMenu(code: SubMenu): void {
    if (code.route) {
      this.route.navigate([code?.route?.path], {
        queryParams: code?.route?.param,
      });
    }
  }
  toggle(): void {
    this.layoutService
      .getSubOpen()
      .pipe(first())
      .subscribe((status: SUB_MENU_TYPE) => {
        this.layoutService.setSubMenuStatus(status === 'out' ? 'in' : 'out');
      });
  }
}

