import { ColorStatus } from './data/colors.model';
import { Color } from './models/color.model';
import { StatusClass } from './models/status.model';

@Component({
  selector: 'dx-status',
  templateUrl: './dx-status.component.html',
  styleUrls: ['./dx-status.component.scss'],
})
export class DxStatusComponent implements OnInit {
  @Input() val!: string;
  @Input() statusCd!: number | string;
  class: StatusClass = {};
  
  ngOnInit(): void {
    this.val = this.val ?? '-';
    this.class = this.showBackgroundColor(this.statusCd);
  }

  /**
   * @description show background color only if the backgroundClass is true
   * @params column Name and status type
   * @return color class name
   */
  showBackgroundColor(colorCd: string | number): StatusClass  {
    const colorObj: Color  | undefined = ColorStatus.COLORS.find(
      (color: Color) => color.code === colorCd
    );
    return {
      color: colorObj?.color,
      opacity: '0.9',
      background: `${String(colorObj?.color)}${'38'}`,
    };
  }
}

