import { ComponentFactory } from '@angular/core';
import { ViewContainerRef } from '@angular/core';
import { ComponentRef } from '@angular/core';
import { 
  AfterContentInit, 
  Component, 
  ComponentFactoryResolver, 
  ContentChildren, 
  EventEmitter,
  Output, 
  QueryList, 
  TemplateRef, 
  ViewChild 
} from '@angular/core';
import { DxTabComponent } from '../dx-tab/dx-tab.component';
import { ContainerDirective } from './container.directive';

@Component({
  selector: 'dx-tab-view',
  templateUrl: './dx-tab-view.component.html',
  styleUrls: ['./dx-tab-view.component.scss']
})
export class DxTabViewComponent implements AfterContentInit {
  dynamicTabs: DxTabComponent[] = [];
  @Output() onSelect: EventEmitter<DxTabComponent> = new EventEmitter<DxTabComponent>();
  @ContentChildren(DxTabComponent) tabs!: QueryList<DxTabComponent>;

  @ViewChild(ContainerDirective, { static: true }) dynamicTabPlaceholder!: ContainerDirective;

  constructor(private readonly _componentFactoryResolver: ComponentFactoryResolver) { }

  // contentChildren are set
  ngAfterContentInit() : void {
    // get all active tabs
    const activeTabs : DxTabComponent[] = this.tabs?.filter((tab : DxTabComponent) => tab?.active);

    // if there is no active tab set, activate the first
    if (activeTabs?.length === 0) {
      this.selectTab(this.tabs?.first);
    }
  }

  openTab(title: string, template: TemplateRef<any>, data: Object, isCloseable : boolean = false) : void {
    // get a component factory for our DxTabComponent
    const componentFactory : ComponentFactory<DxTabComponent> = this._componentFactoryResolver?.resolveComponentFactory(
      DxTabComponent
    );

    // fetch the view container reference from our anchor directive
    const viewContainerRef : ViewContainerRef = this.dynamicTabPlaceholder?.viewContainer;

    // create a component instance
    const componentRef : ComponentRef<DxTabComponent> = viewContainerRef?.createComponent(componentFactory);

    // set the according properties on our component instance
    const instance: DxTabComponent = componentRef?.instance as DxTabComponent;
    instance.title = title;
    instance.template = template;
    instance.dataContext = data;
    instance.isCloseable = isCloseable;

    // remember the dynamic component for rendering the
    // tab navigation headers
    this.dynamicTabs?.push(componentRef?.instance as DxTabComponent);

    // set it active
    this.selectTab(this.dynamicTabs[this.dynamicTabs?.length - 1]);
  }

  selectTab(tab: DxTabComponent) : void {
    // deactivate all tabs
    this.tabs?.toArray()?.forEach((tab : DxTabComponent) => (tab.active = false));
    this.dynamicTabs?.forEach((tab : DxTabComponent) => (tab.active = false));
    // activate the tab the user has clicked on.
    tab.active = true;
    this.onSelect.emit(tab);
  }

  closeTab(tab: DxTabComponent) : void{
    for (let i = 0; i < this.dynamicTabs?.length; i++) {
      if (this.dynamicTabs[i] === tab) {
        // remove the tab from our array
        this.dynamicTabs?.splice(i, 1);
        // destroy our dynamically created component again
        let viewContainerRef : ViewContainerRef = this.dynamicTabPlaceholder?.viewContainer;
        // let viewContainerRef = this.dynamicTabPlaceholder;
        viewContainerRef?.remove(i);

        // set tab index to 1st one
        this.selectTab(this.tabs?.first);
        break;
      }
    }
  }

  closeActiveTab() : void {
    const activeTabs : DxTabComponent[] = this.dynamicTabs?.filter((tab : DxTabComponent) => tab?.active);
    if (activeTabs?.length > 0) {
      // close the 1st active tab (should only be one at a time)
      this.closeTab(activeTabs[0]);
    }
  }
}

