import { Component, EventEmitter, Input, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { Skeleton, SkeletonLoaderModel } from '../../../dx-skeleton-loader';
import { FlexTableData } from '../../interfaces/flex-additional.interface';
import { FlexTableColumn, OnAction, actionType } from '../../interfaces/flex-table.interface';

@Component({
  selector: 'dx-flex-action',
  templateUrl: './flex-action.component.html',
  styleUrls: ['./flex-action.component.scss'],
  encapsulation: ViewEncapsulation.None
})
export class FlexActionComponent<T> implements OnInit {
  @Input() data!: FlexTableData<T>;
  @Input() selectedData!: FlexTableData<T>;
  @Input() columns!: FlexTableColumn<T>;
  @Input() isBusy!: boolean
  @Output() onExpand: EventEmitter<FlexTableData<T>> = new EventEmitter<FlexTableData<T>>();
  @Output() onExternalAction: EventEmitter<OnAction<FlexTableData<T>>> = new EventEmitter<OnAction<FlexTableData<T>>>()
  iconSkeleton: SkeletonLoaderModel = Skeleton.Icon
  allowAction: Array<actionType> | undefined = [];

  ngOnInit(): void {
    this.allowAction = this.columns?.actionType ?? [];
  }

  expand(data?: FlexTableData<T>): void {
    this.onExpand.emit(data);
    this.onActionClick('expand')
  }

  onActionClick(type: actionType): void {
    this.onExternalAction.emit({
      type: type,
      data: this.data
    })
  }

}

