export class FlexInputComponent<T> implements OnInit, ControlValueAccessor {
  @Input() setting!: InputSetting;
  @Input() key!: string;
  @Output() onUpdate: EventEmitter<void> = new EventEmitter<void>();
  // Step 3: Copy paste this stuff here
  onChange: Function = () => {}
  onTouch: Function = () => {}
  showInput!: boolean;

  ngOnInit(): void {
    if(this.setting?.hidenFields) {
      this.showInput = this.setting?.hidenFields?.some((item: string) => item === this.key)
    }
  }

  registerOnChange(fn: Function): void {
    this.onChange = fn;
    
  }
  registerOnTouched(fn: Function): void {
    this.onTouch = fn;
  }

  // Step 4: Define what should happen in this component, if something changes outside
  input!: string;
  writeValue(input: string) {
    this.input = input;
  }
  change():void {
    this.onUpdate.emit();
  }
}

