import {
  trigger,
  state,
  style,
  transition,
  animate,
} from '@angular/animations';
import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import {
  DxFilter,
  DxTableSetting,
  FlexTableColumn,
  OnAction,
} from '../../interfaces/flex-table.interface';
import { CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import { Sort } from '@angular/material/sort';
import { SelectionChange, SelectionModel } from '@angular/cdk/collections';
import { Subscription } from 'rxjs';
import { FlexTableData } from '../../interfaces/flex-additional.interface';
import { MatTable } from '@angular/material/table';
import { PageEvent } from '@angular/material/paginator';
import { Skeleton, SkeletonLoaderModel } from '../../../dx-skeleton-loader/skeleton-loader.constant';

@Component({
  selector: 'dx-flex-table',
  templateUrl: './flex-table.component.html',
  styleUrls: ['./flex-table.component.scss'],
  encapsulation: ViewEncapsulation.None,
  animations: [
    trigger('detailExpand', [
      state(
        'collapsed',
        style({
          height: '0px',
          minHeight: '0',
          visibility: 'hidden',
          display: 'none',
        })
      ),
      state(
        'expanded',
        style({
          height: '*',
          visibility: 'visible',
          padding: '13px',
          display: 'content',
        })
      ),
      transition(
        'expanded <=> collapsed',
        animate('225ms cubic-bezier(0.4, 0.0, 0.2, 1)')
      ),
    ]),
  ],
})
export class FlexTableComponent<T> implements OnInit, OnDestroy {
  @ViewChild('table') table!: MatTable<T>;
  @Input() columns: Array<FlexTableColumn<T>> = [];
  @Input() dataSource: Array<FlexTableData<T>> = [];
  @Input() templateRef!: TemplateRef<any>;
  @Input() isBusy: boolean = false;
  @Input() isAvatar: boolean = false
  @Output() onAction: EventEmitter<OnAction<FlexTableData<T>>> =
    new EventEmitter<OnAction<FlexTableData<T>>>();
  @Output() onSort: EventEmitter<Sort> = new EventEmitter<Sort>();
  @Output() onCheckboxChange: EventEmitter<FlexTableData<T>[]> =
    new EventEmitter<FlexTableData<T>[]>();
  @Output() onFilterClick: EventEmitter<DxFilter> =
    new EventEmitter<DxFilter>();
  @Output() onPaginationClick: EventEmitter<PageEvent> =
    new EventEmitter<PageEvent>();
  @Input() setting!: DxTableSetting;
  @Output() onEventChange: EventEmitter<FlexTableData<T>> = new EventEmitter<
    FlexTableData<T>
  >();
  @Output() onRowSelection: EventEmitter<FlexTableData<T>[]> = new EventEmitter<
    FlexTableData<T>[]
  >();

  clickedRows: SelectionModel<FlexTableData<T>> = new SelectionModel<
    FlexTableData<T>
  >(false, []);
  selection: SelectionModel<FlexTableData<T>> = new SelectionModel<
    FlexTableData<T>
  >(true, []);
  subscription!: Subscription;
  selected: string[] = [];
  displayedColumns: string[] = [];
  displayedColumnsNames: string[] = [];
  expandedElement!: FlexTableData<T> | undefined;
  footerColumns: FlexTableColumn<T>[] = [];
  checkBoxLoader: SkeletonLoaderModel = Skeleton.CheckBox;
  rowSelectLoader: SkeletonLoaderModel = Skeleton.verticalLine;
  ngOnInit(): void {
    this.updateSetting();
    this.displayedColumns = this.selected.concat(
      this.getAllHeaderRef(this.columns)
    );
    this.displayedColumnsNames = this.getAllHeaderName(this.columns);
    this.footerColumns = this.columns?.filter((item: FlexTableColumn<T>) => item?.footer)
    this.subscription = this.selection.changed.subscribe(
      (selected: SelectionChange<FlexTableData<T>>) => {
        this.onCheckboxChange.emit(selected.source.selected);
      }
    );

    if (this.setting?.multiRowSelect) {
      this.clickedRows = new SelectionModel<
        FlexTableData<T>
      >(true, []);
    }

    this.subscription = this.clickedRows.changed.subscribe(
      (selected: SelectionChange<FlexTableData<T>>) => {
        this.onRowSelection.emit(selected.source.selected);
      }
    );
    this.checkedAllSelected();
  }

  /** Whether the number of selected elements matches the total number of rows. */
  isAllSelected(): boolean {
    const numSelected: number = this.selection.selected.length;
    const numRows: number = this.dataSource.length;
    return numSelected === numRows;
  }

  /** Selects all rows if they are not all selected; otherwise clear selection. */
  masterToggle(): void {
    if (this.isAllSelected()) {
      this.selection.clear();
      return;
    }
    this.selection.select(...this.dataSource);
  }

  /** The label for the checkbox on the passed row */
  checkboxLabel(row?: FlexTableData<T>): string {
    if (!row) {
      return `${this.isAllSelected() ? 'deselect' : 'select'} all`;
    }
    return `${this.selection.isSelected(row) ? 'deselect' : 'select'}`;
  }

  drop(event: CdkDragDrop<string[]>) {
    const prevIndex: number = this.dataSource.findIndex(
      (d) => d === event.item.data
    );
    moveItemInArray(this.dataSource, prevIndex, event.currentIndex);
    this.table.renderRows();
  }

  announceSortChange(sortState: Sort): void {
    this.onSort.emit(sortState);
  }

  onFilter(event: DxFilter): void {
    this.onFilterClick.emit(event);
  }
  onPagination(event: PageEvent): void {
    this.onPaginationClick.emit(event);
  }

  onTableExpand(element?: FlexTableData<T>): void {
    this.expandedElement = element;
  }

  action(event: OnAction<FlexTableData<T>>): void {
    this.onAction.emit(event);
  }

  eventChange(event: FlexTableData<T> | undefined): void {
    this.onEventChange.emit(event);
  }

  private getAllHeaderRef(columns: Array<FlexTableColumn<T>>): string[] {
    return columns.map((col: FlexTableColumn<T>) => col.columnDef);
  }
  private getAllHeaderName(columns: Array<FlexTableColumn<T>>): string[] {
    return columns.map((col: FlexTableColumn<T>) => col.title);
  }

  private updateSetting(): void {
    if (this.setting?.rowArrange) {
      this.selected.push('dragHandler');
    }
    if (this.setting?.multiSelect) {
      this.selected.push('select');
    }
  }

  private checkedAllSelected(): void {
    this.dataSource.forEach((val: FlexTableData<T>) => {
      if (val?.multiCheckbox?.checked) {
        this.selection.select(val);
      }
    });
  }
  getTotal(field: string): number {
    return this.dataSource.map((t: FlexTableData<any>) => t?.data[field]).reduce((acc: number | string, value: number | string) => Number(acc) + Number(value), 0);
  }
  ngOnDestroy(): void {
    this.subscription.unsubscribe();
  }
}

