  state = {
    value: 'inactive',
    params: {
      easeTime: this.toastPackage?.config?.easeTime,
      easing: 'ease-in'
    }
  };

  /** hides component when waiting to be displayed */
  @HostBinding('style.display')
  get displayStyle(): string | undefined {
